import type { Job, JobDefinition, JobStatus } from "./types"

export class JobStore<T = unknown> {
  private jobs = new Map<string, Job<T>>()
  private byStatus = new Map<JobStatus, Set<string>>()

  submit(def: JobDefinition): Job<T> {
    const existing = Array.from(this.jobs.values()).find(
      (j) =>
        j.definition.jobType === def.jobType &&
        j.status === "pending",
    )
    if (existing) return existing

    const jobId = crypto.randomUUID()
    const now = Date.now()
    const job: Job<T> = {
      jobId,
      definition: def,
      status: "pending",
      retryCount: 0,
      createdAt: now,
    }
    this.jobs.set(jobId, job)
    this.addToIndex("pending", jobId)
    return job
  }

  get(jobId: string): Job<T> | undefined {
    return this.jobs.get(jobId)
  }

  updateStatus(jobId: string, status: JobStatus, extra?: Partial<Job<T>>): void {
    const job = this.jobs.get(jobId)
    if (!job) return

    this.removeFromIndex(job.status, jobId)
    job.status = status
    if (extra) Object.assign(job, extra)
    this.addToIndex(status, jobId)
  }

  claimNext(
    workerId: string,
    leaseDurationMs: number,
    now: number,
    allowTypes?: string[],
  ): { job: Job<T>; leaseExpiresAt: number } | null {
    const pending = this.getByStatus("pending")
    for (const job of pending) {
      if (allowTypes && !allowTypes.includes(job.definition.jobType)) continue
      const leaseExpiresAt = now + leaseDurationMs
      this.updateStatus(job.jobId, "running", {
        startedAt: now,
        claimedBy: workerId,
        leaseExpiresAt,
      })
      return { job, leaseExpiresAt }
    }
    return null
  }

  complete(jobId: string, result: T, now: number): void {
    this.updateStatus(jobId, "completed", { result, completedAt: now })
  }

  fail(jobId: string, error: string): void {
    const job = this.jobs.get(jobId)
    if (!job) return

    if (job.retryCount < job.definition.maxRetries) {
      job.retryCount++
      this.updateStatus(jobId, "pending", {
        claimedBy: undefined,
        startedAt: undefined,
        leaseExpiresAt: undefined,
      })
    } else {
      this.updateStatus(jobId, "failed", { error, completedAt: Date.now() })
    }
  }

  timeoutExpiredLeases(now: number, leaseDurationMs: number): string[] {
    const timedOut: string[] = []
    const running = this.getByStatus("running")
    for (const job of running) {
      if (job.leaseExpiresAt && now > job.leaseExpiresAt) {
        if (job.retryCount < job.definition.maxRetries) {
          job.retryCount++
          this.updateStatus(job.jobId, "pending", {
            claimedBy: undefined,
            startedAt: undefined,
            leaseExpiresAt: undefined,
          })
        } else {
          this.updateStatus(job.jobId, "timed_out", {
            error: "Lease expired",
            completedAt: now,
          })
        }
        timedOut.push(job.jobId)
      }
    }
    return timedOut
  }

  timeoutJobs(now: number): string[] {
    const timedOut: string[] = []
    const running = this.getByStatus("running")
    for (const job of running) {
      if (job.startedAt && now - job.startedAt > job.definition.timeoutMs) {
        this.fail(job.jobId, `Job timed out after ${job.definition.timeoutMs}ms`)
        timedOut.push(job.jobId)
      }
    }
    return timedOut
  }

  getByStatus(status: JobStatus): Job<T>[] {
    const ids = this.byStatus.get(status)
    if (!ids) return []
    return Array.from(ids)
      .map((id) => this.jobs.get(id)!)
      .filter(Boolean)
  }

  getAll(): Job<T>[] {
    return Array.from(this.jobs.values()).sort((a, b) => a.createdAt - b.createdAt)
  }

  size(): number {
    return this.jobs.size
  }

  clear(): void {
    this.jobs.clear()
    this.byStatus.clear()
  }

  private addToIndex(status: JobStatus, jobId: string): void {
    let set = this.byStatus.get(status)
    if (!set) {
      set = new Set()
      this.byStatus.set(status, set)
    }
    set.add(jobId)
  }

  private removeFromIndex(status: JobStatus, jobId: string): void {
    this.byStatus.get(status)?.delete(jobId)
  }
}

import type { Lease, WorkerIdentity, WorkerClaim } from "./types"
import { JobStore } from "./jobStore"

export class LeaseManager {
  private leases = new Map<string, Lease>()
  private workers = new Map<string, WorkerIdentity>()
  private jobStore: JobStore

  constructor(jobStore: JobStore) {
    this.jobStore = jobStore
  }

  registerWorker(identity: WorkerIdentity): void {
    this.workers.set(identity.workerId, identity)
  }

  unregisterWorker(workerId: string): void {
    this.workers.delete(workerId)
    for (const [leaseId, lease] of this.leases) {
      if (lease.workerId === workerId && lease.status === "active") {
        this.releaseLease(leaseId)
      }
    }
  }

  getWorker(workerId: string): WorkerIdentity | undefined {
    return this.workers.get(workerId)
  }

  getWorkerCount(): number {
    return this.workers.size
  }

  getWorkers(): WorkerIdentity[] {
    return Array.from(this.workers.values())
  }

  claimJob(claim: WorkerClaim): { job: import("./types").Job; lease: Lease } | null {
    const now = claim.claimedAt
    const result = this.jobStore.claimNext(claim.workerId, claim.leaseDurationMs, now)
    if (!result) return null

    const leaseId = crypto.randomUUID()
    const lease: Lease = {
      leaseId,
      jobId: result.job.jobId,
      workerId: claim.workerId,
      status: "active",
      acquiredAt: now,
      expiresAt: result.leaseExpiresAt,
      heartbeatAt: now,
    }
    this.leases.set(leaseId, lease)
    return { job: result.job, lease }
  }

  renewLease(leaseId: string, now: number): boolean {
    const lease = this.leases.get(leaseId)
    if (!lease || lease.status !== "active") return false
    lease.heartbeatAt = now
    return true
  }

  releaseLease(leaseId: string): boolean {
    const lease = this.leases.get(leaseId)
    if (!lease) return false
    lease.status = "released"
    return true
  }

  expireStaleLeases(now: number, leaseDurationMs: number): string[] {
    const expired: string[] = []
    for (const [leaseId, lease] of this.leases) {
      if (lease.status === "active" && now > lease.expiresAt) {
        lease.status = "expired"
        expired.push(leaseId)
      }
    }
    return expired
  }

  getActiveLeaseCount(): number {
    let count = 0
    for (const lease of this.leases.values()) {
      if (lease.status === "active") count++
    }
    return count
  }

  getExpiredLeaseCount(): number {
    let count = 0
    for (const lease of this.leases.values()) {
      if (lease.status === "expired") count++
    }
    return count
  }

  getLease(leaseId: string): Lease | undefined {
    return this.leases.get(leaseId)
  }

  getLeasesByWorker(workerId: string): Lease[] {
    return Array.from(this.leases.values()).filter(
      (l) => l.workerId === workerId,
    )
  }

  clear(): void {
    this.leases.clear()
    this.workers.clear()
  }
}

'use client'

import { RefObject, useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'

interface UseVirtualListOptions {
  totalCount: number
  estimatedRowHeight: number
  overscanScreens?: number
  maxRenderedItems?: number
  preserveKey?: string
}

interface VirtualItem {
  index: number
  offsetTop: number
  height: number
}

interface VirtualRange {
  start: number
  end: number
  paddingTop: number
  paddingBottom: number
  totalHeight: number
  virtualItems: VirtualItem[]
}

const savedScrollPositions = new Map<string, number>()

export function useVirtualList<T>(
  items: readonly T[],
  {
    totalCount,
    estimatedRowHeight,
    overscanScreens = 3,
    maxRenderedItems = 100,
    preserveKey,
  }: UseVirtualListOptions,
): VirtualRange & {
  containerRef: RefObject<HTMLDivElement | null>
  topSentinelRef: RefObject<HTMLDivElement | null>
  bottomSentinelRef: RefObject<HTMLDivElement | null>
  visibleItems: readonly T[]
  measureElement: (index: number, element: HTMLElement | null) => void
} {
  const containerRef = useRef<HTMLDivElement | null>(null)
  const topSentinelRef = useRef<HTMLDivElement | null>(null)
  const bottomSentinelRef = useRef<HTMLDivElement | null>(null)
  const heightsRef = useRef(new Map<number, number>())
  const [scrollState, setScrollState] = useState({ scrollTop: 0, viewportHeight: 0 })

  const getHeight = useCallback(
    (index: number) => heightsRef.current.get(index) ?? estimatedRowHeight,
    [estimatedRowHeight],
  )

  const getOffsetTop = useCallback(
    (index: number) => {
      let offset = 0
      for (let i = 0; i < index; i += 1) offset += getHeight(i)
      return offset
    },
    [getHeight],
  )

  const totalHeight = useMemo(() => {
    let measuredDelta = 0
    heightsRef.current.forEach((height) => {
      measuredDelta += height - estimatedRowHeight
    })
    return Math.max(0, totalCount * estimatedRowHeight + measuredDelta)
  }, [estimatedRowHeight, totalCount, scrollState])

  const range = useMemo(() => {
    const { scrollTop, viewportHeight } = scrollState
    const overscanPixels = viewportHeight * overscanScreens
    const requestedStart = Math.max(0, Math.floor((scrollTop - overscanPixels) / estimatedRowHeight))
    const requestedEnd = Math.min(
      totalCount,
      Math.ceil((scrollTop + viewportHeight + overscanPixels) / estimatedRowHeight),
    )
    const visibleCenter = Math.max(0, Math.floor((scrollTop + viewportHeight / 2) / estimatedRowHeight))
    const requestedCount = Math.max(1, requestedEnd - requestedStart)
    const cappedCount = Math.min(maxRenderedItems, requestedCount, totalCount)
    const start = requestedCount > maxRenderedItems
      ? Math.max(0, Math.min(totalCount - cappedCount, visibleCenter - Math.floor(cappedCount / 2)))
      : requestedStart
    const end = Math.min(totalCount, start + cappedCount)
    const paddingTop = getOffsetTop(start)
    const virtualItems = Array.from({ length: end - start }, (_, position) => {
      const index = start + position
      return { index, offsetTop: getOffsetTop(index), height: getHeight(index) }
    })
    const renderedHeight = virtualItems.reduce((sum, item) => sum + item.height, 0)

    return {
      start,
      end,
      paddingTop,
      paddingBottom: Math.max(0, totalHeight - paddingTop - renderedHeight),
      totalHeight,
      virtualItems,
    }
  }, [estimatedRowHeight, getHeight, getOffsetTop, maxRenderedItems, overscanScreens, scrollState, totalCount, totalHeight])

  const updateScrollState = useCallback(() => {
    const container = containerRef.current
    if (!container) return
    const next = { scrollTop: container.scrollTop, viewportHeight: container.clientHeight }
    if (preserveKey) savedScrollPositions.set(preserveKey, next.scrollTop)
    setScrollState((previous) => (
      previous.scrollTop === next.scrollTop && previous.viewportHeight === next.viewportHeight ? previous : next
    ))
  }, [preserveKey])

  useLayoutEffect(() => {
    const container = containerRef.current
    if (!container) return
    if (preserveKey) container.scrollTop = savedScrollPositions.get(preserveKey) ?? container.scrollTop
    updateScrollState()
  }, [preserveKey, updateScrollState])

  useEffect(() => {
    const container = containerRef.current
    if (!container) return
    const observer = new IntersectionObserver(updateScrollState, { root: container })
    if (topSentinelRef.current) observer.observe(topSentinelRef.current)
    if (bottomSentinelRef.current) observer.observe(bottomSentinelRef.current)
    container.addEventListener('scroll', updateScrollState, { passive: true })
    const resizeObserver = new ResizeObserver(updateScrollState)
    resizeObserver.observe(container)
    return () => {
      container.removeEventListener('scroll', updateScrollState)
      observer.disconnect()
      resizeObserver.disconnect()
    }
  }, [updateScrollState])

  const measureElement = useCallback((index: number, element: HTMLElement | null) => {
    if (!element) return
    const nextHeight = element.getBoundingClientRect().height
    if (nextHeight > 0 && heightsRef.current.get(index) !== nextHeight) {
      heightsRef.current.set(index, nextHeight)
      updateScrollState()
    }
  }, [updateScrollState])

  return {
    ...range,
    containerRef,
    topSentinelRef,
    bottomSentinelRef,
    visibleItems: items.slice(range.start, range.end),
    measureElement,
  }
}

import {
  ADVISORY_SOURCE_VERSION,
  DEFAULT_ADVISORY_SOURCES,
  PERFORMANCE_BUDGET_MS,
  buildFindings,
  buildReport,
  checkCanaryGate,
  parsePackageJson,
  redactReport,
  type AdvisorySource,
  type CanaryGateResult,
  type DeploymentChannel,
  type PackageSource,
  type ParsedDependency,
  type ScanReport,
} from "../lib/vulnerability";

export type ScanListener = (report: ScanReport) => void;

export interface DependencyScanOptions {
  packageSources?: PackageSource[];
  advisorySources?: AdvisorySource[];
  channel?: DeploymentChannel;
  now?: () => number;
  clock?: () => number;
  historyLimit?: number;
}

const DEFAULT_HISTORY_LIMIT = 50;

export function createDefaultPackageSources(): PackageSource[] {
  const cache: { deps?: ParsedDependency[] } = {};

  return [
    {
      name: "app",
      parse: () => {
        if (cache.deps) return { dependencies: cache.deps };
        try {
           
          // eslint-disable-next-line @typescript-eslint/no-require-imports
          const pkg = require("../../package.json");
          cache.deps = parsePackageJson(pkg);
          return { dependencies: cache.deps };
        } catch {
          return { dependencies: [] };
        }
      },
    },
  ];
}

export class DependencyScanner {
  private packageSources: Map<string, PackageSource>;
  private advisorySources: Map<string, AdvisorySource>;
  private listeners = new Set<ScanListener>();
  private history: ScanReport[] = [];
  private channel: DeploymentChannel;
  private now: () => number;
  private clock: () => number;
  private historyLimit: number;
  private lastReport: ScanReport | null = null;

  constructor(options: DependencyScanOptions = {}) {
    this.packageSources = new Map(
      (options.packageSources ?? createDefaultPackageSources()).map((s) => [
        s.name,
        s,
      ]),
    );
    this.advisorySources = new Map(
      (options.advisorySources ?? DEFAULT_ADVISORY_SOURCES).map((s) => [
        s.name,
        s,
      ]),
    );
    this.channel = options.channel ?? "stable";
    this.now = options.now ?? (() => Date.now());
    this.clock =
      options.clock ??
      (() =>
        typeof performance !== "undefined" ? performance.now() : Date.now());
    this.historyLimit = options.historyLimit ?? DEFAULT_HISTORY_LIMIT;
  }

  registerPackageSource(source: PackageSource): void {
    this.packageSources.set(source.name, source);
  }

  unregisterPackageSource(name: string): void {
    this.packageSources.delete(name);
  }

  setChannel(channel: DeploymentChannel): void {
    this.channel = channel;
  }

  subscribe(listener: ScanListener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  getHistory(): ScanReport[] {
    return [...this.history];
  }

  getLastReport(): ScanReport | null {
    return this.lastReport;
  }

  /**
   * Scan a single registered package source. Critical path — must stay <100ms.
   */
  async scanSource(sourceName: string): Promise<ScanReport> {
    const started = this.clock();
    const source = this.packageSources.get(sourceName);

    if (!source) {
      const durationMs = this.clock() - started;
      const report: ScanReport = {
        ok: false,
        findings: [],
        metrics: {
          durationMs,
          withinBudget: durationMs < PERFORMANCE_BUDGET_MS,
          findingCount: 0,
          criticalCount: 0,
          highCount: 0,
          mediumCount: 0,
          lowCount: 0,
          totalDependencies: 0,
          scannedAt: this.now(),
        },
        channel: this.channel,
        source: sourceName,
        advisorySourceVersion: ADVISORY_SOURCE_VERSION,
      };
      this.record(report);
      return report;
    }

    let deps: ParsedDependency[];
    try {
      const parsed = source.parse();
      deps = parsed.dependencies;
    } catch (error) {
      const durationMs = this.clock() - started;
      const report: ScanReport = {
        ok: false,
        findings: [],
        metrics: {
          durationMs,
          withinBudget: durationMs < PERFORMANCE_BUDGET_MS,
          findingCount: 0,
          criticalCount: 0,
          highCount: 0,
          mediumCount: 0,
          lowCount: 0,
          totalDependencies: 0,
          scannedAt: this.now(),
        },
        channel: this.channel,
        source: sourceName,
        advisorySourceVersion: ADVISORY_SOURCE_VERSION,
      };
      this.record(report);
      return report;
    }

    const allAdvisories = [];
    for (const advSource of this.advisorySources.values()) {
      try {
        const advisories = await advSource.fetch(deps);
        allAdvisories.push(...advisories);
      } catch (error) {
        console.warn(
          `Advisory source "${advSource.name}" failed:`,
          error,
        );
      }
    }

    const findings = buildFindings(deps, allAdvisories);
    const durationMs = this.clock() - started;
    const report = redactReport(
      buildReport(sourceName, findings, deps.length, durationMs, this.channel),
    );
    this.record(report);
    return report;
  }

  /**
   * Scan all registered package sources.
   */
  async scanAll(): Promise<ScanReport> {
    const started = this.clock();
    const sources = [...this.packageSources.keys()];

    const results = await Promise.all(
      sources.map((name) => this.scanSource(name)),
    );

    const allFindings = results.flatMap((r) => r.findings);
    const totalDeps = results.reduce(
      (sum, r) => sum + r.metrics.totalDependencies,
      0,
    );
    const durationMs = this.clock() - started;
    const report = redactReport(
      buildReport("*", allFindings, totalDeps, durationMs, this.channel),
    );
    this.lastReport = report;
    this.record(report);
    return report;
  }

  checkCanaryGate(): CanaryGateResult {
    return checkCanaryGate(this.history, this.channel);
  }

  private record(report: ScanReport): void {
    this.history.push(report);
    if (this.history.length > this.historyLimit) {
      this.history.splice(0, this.history.length - this.historyLimit);
    }
    for (const listener of this.listeners) {
      listener(report);
    }
  }
}

let sharedScanner: DependencyScanner | null = null;

export function getDependencyScanner(): DependencyScanner {
  if (!sharedScanner) {
    sharedScanner = new DependencyScanner();
  }
  return sharedScanner;
}

export function resetDependencyScannerForTests(): void {
  sharedScanner = null;
}

interface BluetoothDevice {
  name: string;
  gatt: BluetoothRemoteGATTServer;
}

interface BluetoothRemoteGATTServer {
  connect(): Promise<BluetoothRemoteGATTServer>;
  disconnect(): Promise<void>;
  getPrimaryService(service: string): Promise<BluetoothRemoteGATTService>;
  connected: boolean;
}

interface BluetoothRemoteGATTService {
  getCharacteristic(characteristic: string): Promise<BluetoothRemoteGATTCharacteristic>;
}

interface BluetoothRemoteGATTCharacteristic {
  writeValue(value: Uint8Array): Promise<void>;
  startNotifications(): Promise<void>;
  stopNotifications(): Promise<void>;
  addEventListener(event: string, callback: (event: any) => void): void;
  removeEventListener(event: string, callback: (event: any) => void): void;
  value: DataView | null;
}

/* eslint-disable */
interface NavigatorBluetooth {
  requestDevice(options: any): Promise<BluetoothDevice>;
}

interface NavigatorWithBluetooth extends Navigator {
  bluetooth: NavigatorBluetooth;
}

declare global {
  interface Navigator extends NavigatorWithBluetooth {}
}

/**
 * File System Access API Type Declarations
 */

interface FilePickerAcceptType {
  description?: string;
  accept: Record<string, string[]>;
}

interface SaveFilePickerOptions {
  suggestedName?: string;
  types?: FilePickerAcceptType[];
  excludeAcceptAllOption?: boolean;
  id?: string;
  startIn?: FileSystemHandle | string;
}

interface FileSystemHandlePermissionDescriptor {
  name: 'file' | 'directory';
  mode?: 'read' | 'readwrite';
}

interface FileSystemCreateWritableOptions {
  keepExistingData?: boolean;
}

interface FileSystemWritableFileStream extends WritableStream {
  write(data: any): Promise<void>;
  seek(position: number): Promise<void>;
  truncate(size: number): Promise<void>;
  close(): Promise<void>;
}

interface FileSystemFileHandle extends FileSystemHandle {
  getFile(): Promise<File>;
  createWritable(options?: FileSystemCreateWritableOptions): Promise<FileSystemWritableFileStream>;
}

/* eslint-disable */
interface FileSystemHandle {
  readonly kind: 'file' | 'directory';
  readonly name: string;
  queryPermission(descriptor?: FileSystemHandlePermissionDescriptor): Promise<PermissionState>;
  requestPermission(descriptor?: FileSystemHandlePermissionDescriptor): Promise<PermissionState>;
  isSameEntry(other: FileSystemHandle): boolean;
}

declare global {
  interface Window {
    showSaveFilePicker(options?: SaveFilePickerOptions): Promise<FileSystemFileHandle>;
  }
}

export {};
